def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    prev_aggressive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                req = opp.get('water_requirement', WATER_REQ)
                if req > 0:
                    prev_aggressive.append(bid / float(req))

    if not alive_opponents:
        return max(0.0, min(budget, 18.0))

    total_players = 1 + len(alive_opponents)
    est_units = supply / float(WATER_REQ)
    scarcity = est_units < total_players
    severe_scarcity = est_units < max(1.5, total_players * 0.6)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0
    high_pressure = highest_prev >= 90
    medium_pressure = highest_prev >= 60 or avg_prev >= 50

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 7:
        urgency += 2
    else:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if severe_scarcity:
        urgency += 2
    elif scarcity:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 7:
        target = max(92.0, highest_prev + 2.5)
        if high_pressure:
            target = max(target, 108.0)
    elif urgency >= 5:
        if severe_scarcity:
            target = max(72.0, highest_prev + 1.5)
        else:
            target = max(58.0, avg_prev + 4.0)
    elif urgency >= 3:
        if medium_pressure and scarcity:
            target = max(46.0, avg_prev + 2.0)
        else:
            target = 32.0 if not scarcity else 40.0
    else:
        if high_pressure:
            target = 18.0
        elif medium_pressure:
            target = 24.0
        else:
            target = 20.0

    if budget < DAILY_SALARY * 1.2 and urgency < 6:
        target = min(target, 45.0)
    if budget < 35:
        target = min(target, budget)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, min(budget, 95.0))

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from traces of alive opponents
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # If we have data, infer pressure from the top bidder (Cindy-like behavior)
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid: scale with supply scarcity (lower supply -> higher bid)
    # Normalize scarcity in [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, scarcity))

    # Target bid level: moderate, but increase if others previously bid high
    # Cindy survived with ~115 avg; Alex/David died with ~28 avg.
    # We'll sit between: enough to beat low bidders, not as high as Cindy.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        # High-pressure environment: bid closer to but still below top
        base = 0.75 * highest_prev_bid
    elif highest_prev_bid >= DAILY_SALARY * 0.7:
        base = 0.55 * highest_prev_bid
    else:
        base = DAILY_SALARY * (0.45 + 0.25 * scarcity)

    # Health urgency: if low hp or already accruing no-water days, ramp
    if my_hp <= 2.0:
        urgency_mult = 1.15
    elif my_hp <= 4.0:
        urgency_mult = 1.05
    else:
        urgency_mult = 1.0

    # If we've already gone multiple days without water, increase bid
    if my_no_water_days >= 2:
        urgency_mult *= 1.10
    if my_no_water_days >= 3:
        urgency_mult *= 1.20

    bid = base * urgency_mult

    # Ensure bid is at least enough to compete when supply is tight
    # Use supply slots estimate to avoid too-low bids.
    # Estimated number of water units available ~ supply/WATER_REQ
    units = supply / float(WATER_REQ) if WATER_REQ > 0 else 1.0
    # If units small, increase floor
    if units <= 1.7:
        bid = max(bid, DAILY_SALARY * (0.55 + 0.25 * scarcity))
    elif units <= 2.2:
        bid = max(bid, DAILY_SALARY * (0.45 + 0.15 * scarcity))

    # Budget cap and non-negative
    bid = max(0.0, min(bid, my_budget))

    # If budget is extremely low, still bid something to avoid total starvation
    if my_budget <= 1.0:
        return 0.0

    # Slightly vary with day to avoid ties (bounded)
    jitter = ((day % 5) - 2) * 1.0
    bid = max(0.0, bid + jitter)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_current_hp = my_status['hp']
    my_budget = my_status['budget']
    current_supply = day_context['supply']

    bid_very_aggressive = DAILY_SALARY * 0.98
    bid_aggressive = DAILY_SALARY * 0.9
    bid_high_moderate = DAILY_SALARY * 0.8
    bid_moderate = DAILY_SALARY * 0.7
    bid_low_moderate = DAILY_SALARY * 0.6
    bid_conservative = DAILY_SALARY * 0.4

    bid_amount = 0.0

    if not yesterday_bids:
        # Day 1 or no previous bids from opponents
        if my_current_hp <= 2:
            bid_amount = bid_aggressive
        elif my_current_hp <= 5:
            bid_amount = bid_high_moderate
        else:
            # If supply is tight, be more aggressive initially
            if current_supply < WATER_REQ * (len(alive_opponents) + 1):
                bid_amount = bid_high_moderate
            else:
                bid_amount = bid_moderate
    else:
        highest_prev_bid = max(yesterday_bids)

        if my_current_hp <= 2:
            bid_amount = max(bid_aggressive, highest_prev_bid + 1.5)
        elif my_current_hp <= 5:
            bid_amount = max(bid_high_moderate, highest_prev_bid + 1.5)
        else:
            # Healthy HP
            if highest_prev_bid >= DAILY_SALARY * 0.9: # Opponent bid very high
                if current_supply <= WATER_REQ + 2: # Very tight supply
                    bid_amount = max(bid_high_moderate, highest_prev_bid + 1.5)
                else:
                    # If supply is not extremely tight, and I'm healthy, conserve budget
                    bid_amount = bid_moderate
            else:
                # Opponent bid moderate or low
                bid_amount = max(bid_moderate, highest_prev_bid + 1.5)

    final_bid = min(my_budget, bid_amount)
    return max(0.0, final_bid)

